package com.gcorp.service.app.mvflix_media_ingestion.infrastructure.security;
import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.security.config.annotation.web.reactive.EnableWebFluxSecurity; import org.springframework.security.config.web.server.ServerHttpSecurity; import org.springframework.security.web.server.SecurityWebFilterChain;
@Configuration @EnableWebFluxSecurity public class SecurityConfig { @Bean SecurityWebFilterChain security(ServerHttpSecurity h){return h.csrf(ServerHttpSecurity.CsrfSpec::disable).authorizeExchange(e->e.pathMatchers("/actuator/**").permitAll().anyExchange().authenticated()).oauth2ResourceServer(o->o.jwt()).build();} }
